declarations.code:
constexpr auto operator[](difference_type n) const

    requires /*all-random-access*/<
        Const, Views...>;

intro:
Obtains a std::tuple that consists of underlying pointed-to elements at given offset relative to current location.

Equivalent to:

return /*tuple-transform*/([&]<class I>(I& i) -> decltype(auto) {
           return i[iter_difference_t<I>(n)];
       }, current_);

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::ranges::zip_view{values, values};
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
